import unittest

from checkout import PaymentError, charge


class RejectingGateway:
    def charge(self, amount):
        raise PaymentError("declined")


class ChargeFailureTests(unittest.TestCase):
    def test_rejection_is_not_reported_as_success(self):
        with self.assertRaises(PaymentError):
            charge(RejectingGateway(), 5)
